import { Injectable, InjectionToken, inject, DOCUMENT } from '@angular/core';

export interface WindowWithAnalytics extends Window {
  dataLayer: Record<string, unknown>[];
}

/**
 * Type definition based on Marketing Cloud Confluence documentation
 *
 * https://questrade.atlassian.net/wiki/spaces/AGILE/pages/344555603/GA+Events
 *
 * https://questrade.atlassian.net/wiki/spaces/AGILE/pages/363956251/Create+GTM+module+for+MFE+tool+library+for+shadow+DOM+tracking
 */
export type QAnalyticsEvent = { [key: string]: string | boolean };

export const Q_ANALYTICS_ENABLED = new InjectionToken('Q_ANALYTICS_ENABLED', {
  providedIn: 'root',
  factory: (): boolean => true,
});

@Injectable({
  providedIn: 'root',
})
export class QAnalyticsService {
  isEnabled = inject(Q_ANALYTICS_ENABLED);

  private _window = inject(DOCUMENT).defaultView as typeof globalThis & WindowWithAnalytics;
  private debounceTimeout: ReturnType<typeof setTimeout> | null = null;

  public sendEvent(analyticsEvent: QAnalyticsEvent): void {
    if (!this.isEnabled) return;

    if (this.debounceTimeout) {
      clearTimeout(this.debounceTimeout);
    }

    this.debounceTimeout = setTimeout(() => {
      this._window.dataLayer?.push(analyticsEvent);
      this.debounceTimeout = null;
    }, 200);
  }
}
